1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResults = {
19	  results: unknown[];
20	};
21	
22	const sum = (amounts: number[]): number =>
23	  amounts.reduce((total, amount) => total + amount, 0);
24	
25	const PROCESSING_FEE = 5;
26	
27	// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
28	// 115.00000000000001); snap to cent precision so only genuine fractions round up.
29	const roundUpInMHPCOsFavour = (amount: number): number =>
30	  Math.ceil(Number(amount.toFixed(6)));
31	
32	// One entry per insurable type: every fact the office knows about a type lives
33	// here, so adding a type is a single edit.
34	type ItemKind = {
35	  basePremium: number;
36	  isComponent: boolean;
37	};
38	
39	const ITEM_CATALOGUE: Record<string, ItemKind> = {
40	  sword: { basePremium: 100, isComponent: false },
41	  amulet: { basePremium: 60, isComponent: false },
42	  staff: { basePremium: 80, isComponent: false },
43	  potion: { basePremium: 40, isComponent: false },
44	  rune: { basePremium: 25, isComponent: true },
45	  moonstone: { basePremium: 25, isComponent: true },
46	};
47	
48	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
49	
50	const kindOf = (item: Item): ItemKind => ITEM_CATALOGUE[item.type];
51	
52	const basePremiumOf = (item: Item): number => kindOf(item).basePremium;
53	
54	const BLOCK_SIZE = 3;
55	const BLOCK_BASE_PREMIUM = 60;
56	
57	const groupByType = (items: Item[]): Item[][] => {
58	  const itemsByType = new Map<string, Item[]>();
59	
60	  for (const item of items) {
61	    const sameTypeItems = itemsByType.get(item.type);
62	    if (sameTypeItems) sameTypeItems.push(item);
63	    else itemsByType.set(item.type, [item]);
64	  }
65	
66	  return [...itemsByType.values()];
67	};
68	
69	const isComponent = (item: Item): boolean => kindOf(item).isComponent;
70	
71	// A block is a special price for exactly 3 alike components; any other count,
72	// and any main item, is charged per item.
73	const sameTypeBasePremiumOf = (sameTypeItems: Item[]): number =>
74	  sameTypeItems.length === BLOCK_SIZE && isComponent(sameTypeItems[0])
75	    ? BLOCK_BASE_PREMIUM
76	    : sum(sameTypeItems.map(basePremiumOf));
77	
78	const policyBasePremiumOf = (items: Item[]): number =>
79	  sum(groupByType(items).map(sameTypeBasePremiumOf));
80	
81	const CURSE_SURCHARGE_RATE = 0.5;
82	
83	// Item-specific surcharges are charged on that item's own base premium, not on
84	// the policy total.
85	const itemSurchargesOf = (item: Item): number =>
86	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
87	
88	const quote = (step: QuoteStep): number => {
89	  const policyBasePremium = policyBasePremiumOf(step.items);
90	  const itemSurcharges = sum(step.items.map(itemSurchargesOf));
91	  const firstInsuranceSurcharge =
92	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
93	
94	  return roundUpInMHPCOsFavour(
95	    policyBasePremium +
96	      itemSurcharges +
97	      firstInsuranceSurcharge +
98	      PROCESSING_FEE,
99	  );
100	};
101	
102	export const runScenario = (scenario: Scenario): ScenarioResults => {
103	  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
104	};
